<script setup>
import { computed, onMounted, ref } from 'vue';
import AdWizard from '../components/AdWizard.vue';
import { adService, bankService, locationService } from '../services';
import { useUserAds } from '../stores/useUserAds';
import { createLogger, logException } from '../utils/logger';

const logger = createLogger('MyAdsView');
const adsStore = useUserAds();
const activeStatus = ref('');
const notice = ref('');
const editingAd = ref(null);
const deletingAd = ref(null);
const banks = ref([]);
const provinces = ref([]);
const tabs = [{ value: '', label: 'همه' }, { value: 'published', label: 'منتشر شده' }, { value: 'pending_approval', label: 'در انتظار بررسی' }, { value: 'rejected', label: 'رد شده' }, { value: 'expired', label: 'منقضی شده' }];
const statusText = (status) => ({ published: 'منتشر شده', pending_approval: 'در انتظار بررسی', rejected: 'رد شده', expired: 'منقضی شده', handed_over: 'واگذار شده' }[status] || 'نامشخص');
const filteredAds = computed(() => activeStatus.value ? adsStore.ads.filter((ad) => ad.status === activeStatus.value) : adsStore.ads);
const money = (value) => `${new Intl.NumberFormat('fa-IR').format(Number(value || 0))} تومان`;

async function refresh() { await adsStore.fetchAds(activeStatus.value); }
async function changeStatus(status) { activeStatus.value = status; try { await refresh(); } catch (exception) { notice.value = 'دریافت آگهی‌ها با خطا مواجه شد.'; } }
function openCreate() { editingAd.value = {}; }
function editAd(ad) { logger.info('editAd', 'Edit wizard opened', { advertisementId: ad.id }); editingAd.value = ad; }
async function markTransferred(ad) { try { await adService.toggleStatus(ad.id, 'handed_over'); notice.value = 'آگهی به وضعیت واگذار شده تغییر کرد.'; await refresh(); } catch (exception) { logger.error('markTransferred', 'Status change failed', logException(exception)); notice.value = 'تغییر وضعیت آگهی انجام نشد.'; } }
async function removeAd() { if (!deletingAd.value) return; try { await adService.delete(deletingAd.value.id); notice.value = 'آگهی حذف شد.'; deletingAd.value = null; await refresh(); } catch (exception) { logger.error('removeAd', 'Delete failed', logException(exception)); notice.value = 'حذف آگهی انجام نشد.'; } }
async function loadOptions() { const [bankResponse, locationResponse] = await Promise.all([bankService.getAll(), locationService.getProvinces()]); banks.value = bankResponse.data || bankResponse; provinces.value = locationResponse.data || locationResponse; }
onMounted(async () => { try { await Promise.all([adsStore.fetchAds(), loadOptions()]); } catch (exception) { notice.value = 'اطلاعات آگهی‌ها دریافت نشد.'; } });
</script>

<template>
<section class="module-view" dir="rtl" aria-labelledby="my-ads-title">
    <header class="module-header"><div><span class="module-kicker">مدیریت آگهی‌ها</span><h1 id="my-ads-title">آگهی‌های من</h1><p>وضعیت و عملکرد آگهی‌های ثبت‌شده خود را مدیریت کنید.</p></div><button class="primary-action" type="button" @click="openCreate"><i class="pi pi-plus"></i>ثبت آگهی جدید</button></header>
    <p v-if="notice" class="module-notice" role="status">{{ notice }}</p>
    <div class="status-tabs" role="tablist"><button v-for="tab in tabs" :key="tab.value" type="button" role="tab" :aria-selected="activeStatus === tab.value" :class="{ active: activeStatus === tab.value }" @click="changeStatus(tab.value)">{{ tab.label }}<span>{{ tab.value ? adsStore.ads.filter((ad) => ad.status === tab.value).length : adsStore.ads.length }}</span></button></div>
    <div v-if="adsStore.loading" class="module-loading" role="status"><i class="pi pi-spin pi-spinner"></i>در حال دریافت آگهی‌ها...</div>
    <div v-else-if="!filteredAds.length" class="module-empty"><i class="pi pi-inbox"></i><h2>آگهی‌ای در این بخش ندارید</h2><button class="primary-action" type="button" @click="openCreate"><i class="pi pi-plus"></i>ثبت آگهی جدید</button></div>
    <div v-else class="user-ads-list"><article v-for="ad in filteredAds" :key="ad.id" class="user-ad-item"><div class="ad-bank-icon"><i class="pi pi-building"></i></div><div class="ad-item-body"><div class="ad-item-meta"><span>{{ ad.type === 'supply' ? 'عرضه' : 'تقاضا' }}</span><b :class="`status-${ad.status}`">{{ statusText(ad.status) }}</b></div><h2>{{ ad.title }}</h2><p>{{ ad.bank }}<span v-if="ad.plan || ad.bank_plan?.title">، {{ ad.plan || ad.bank_plan?.title }}</span></p><div class="ad-item-facts"><span>مبلغ وام<strong>{{ money(ad.loan_amount ?? ad.amount) }}</strong></span><span>قیمت واگذاری<strong>{{ money(ad.assignment_price ?? ad.price) }}</strong></span><span>موقعیت<strong>{{ ad.province }}، {{ ad.city }}</strong></span></div><p v-if="ad.status === 'rejected' && ad.rejection_reason" class="rejection-reason"><i class="pi pi-info-circle"></i>{{ ad.rejection_reason }}</p></div><div class="ad-actions"><button type="button" title="ویرایش آگهی" @click="editAd(ad)"><i class="pi pi-pencil"></i></button><button v-if="!['handed_over', 'expired'].includes(ad.status)" type="button" title="تغییر وضعیت به واگذار شد" @click="markTransferred(ad)"><i class="pi pi-check"></i></button><button type="button" title="حذف آگهی" @click="deletingAd = ad"><i class="pi pi-trash"></i></button></div></article></div>
    <div v-if="editingAd" class="wizard-overlay"><section class="wizard-dialog" role="dialog" aria-modal="true"><header><h2>{{ editingAd.id ? 'ویرایش آگهی' : 'ثبت آگهی جدید' }}</h2><button type="button" aria-label="بستن" @click="editingAd = null"><i class="pi pi-times"></i></button></header><AdWizard :banks="banks" :provinces="provinces" :advertisement="editingAd.id ? editingAd : null" @saved="async () => { editingAd = null; notice = 'آگهی شما ثبت شد و پس از بررسی تیم مستروام منتشر خواهد شد'; await refresh(); }" @cancel="editingAd = null" /></section></div>
    <div v-if="deletingAd" class="confirm-overlay"><section class="confirm-dialog" role="alertdialog" aria-modal="true"><i class="pi pi-trash"></i><h2>حذف آگهی؟</h2><p>این آگهی از فهرست شما حذف خواهد شد.</p><footer><button type="button" class="secondary-action" @click="deletingAd = null">انصراف</button><button type="button" class="danger-action" @click="removeAd">حذف آگهی</button></footer></section></div>
</section>
</template>

<style scoped>
.module-view{direction:rtl}.module-header{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:26px}.module-kicker{color:#a62626;font-size:11px;font-weight:700}.module-header h1{margin:7px 0 5px;font-size:24px;color:#202a35}.module-header p{margin:0;color:#78848c;font-size:12px}.primary-action,.secondary-action,.danger-action{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:11px 16px;border-radius:7px;cursor:pointer;font:inherit;font-size:12px;font-weight:700}.primary-action{border:0;background:#a62626;color:#fff}.primary-action:hover{background:#861f1f}.module-notice{padding:11px 14px;border-right:3px solid #a62626;background:#fff5f2;color:#812828;font-size:12px}.status-tabs{display:flex;gap:22px;border-bottom:1px solid #e7eaec;margin-bottom:18px}.status-tabs button{display:inline-flex;align-items:center;gap:7px;padding:12px 3px;border:0;border-bottom:2px solid transparent;background:transparent;color:#77838c;cursor:pointer;font:inherit;font-size:12px}.status-tabs button.active{border-bottom-color:#a62626;color:#a62626;font-weight:700}.status-tabs span{padding:2px 7px;border-radius:12px;background:#f1f3f4;color:#69757d;font-size:10px}.user-ads-list{display:grid;gap:12px}.user-ad-item{display:grid;grid-template-columns:54px minmax(0,1fr) auto;align-items:center;gap:16px;padding:17px;border:1px solid #edf0f2;border-radius:10px;background:#fff}.ad-bank-icon{display:grid;place-items:center;width:54px;height:54px;border-radius:10px;background:#f3f5f6;color:#68747c;font-size:21px}.ad-item-body{min-width:0}.ad-item-meta{display:flex;justify-content:space-between;align-items:center;gap:10px}.ad-item-meta span{color:#7c8890;font-size:10px}.ad-item-meta b{padding:5px 8px;border-radius:13px;font-size:10px;font-weight:500}.status-published{background:#ecf8f1;color:#287b50}.status-pending_approval{background:#fff6e6;color:#a56824}.status-rejected,.status-expired{background:#fff0ef;color:#ae4747}.status-handed_over{background:#f0f2f3;color:#69757d}.ad-item-body h2{overflow:hidden;margin:7px 0 4px;color:#202a35;font-size:14px;text-overflow:ellipsis;white-space:nowrap}.ad-item-body p{margin:0;color:#78848c;font-size:11px}.ad-item-facts{display:flex;gap:18px;margin-top:14px;color:#8a959b;font-size:10px}.ad-item-facts strong{display:block;margin-top:4px;color:#394850;font-size:11px}.ad-actions{display:flex;gap:5px}.ad-actions button{width:30px;height:30px;border:1px solid #e4e8ea;border-radius:6px;background:#fff;color:#71808c;cursor:pointer}.ad-actions button:hover{border-color:#a62626;color:#a62626}.rejection-reason{display:flex;gap:6px;margin-top:12px!important;padding:8px;background:#fff5f2;color:#a12d2d!important}.wizard-overlay,.confirm-overlay{position:fixed;inset:0;z-index:110;display:grid;place-items:center;padding:16px;background:rgba(32,42,53,.48)}.wizard-dialog{width:min(720px,100%);max-height:calc(100vh - 32px);overflow:auto;border-radius:12px;background:#fff}.wizard-dialog>header{display:flex;justify-content:space-between;align-items:center;padding:18px 22px;border-bottom:1px solid #f0f2f4}.wizard-dialog h2,.confirm-dialog h2{margin:0;color:#202a35;font-size:17px}.wizard-dialog header button{border:0;background:transparent;color:#71808c;cursor:pointer}.confirm-dialog{width:min(360px,100%);padding:24px;text-align:center;border-radius:12px;background:#fff}.confirm-dialog>i{color:#a62626;font-size:24px}.confirm-dialog p{color:#78848c;font-size:12px}.confirm-dialog footer{display:flex;justify-content:center;gap:8px;margin-top:20px}.secondary-action{border:1px solid #dfe4e8;background:#fff;color:#52616b}.danger-action{border:0;background:#a62626;color:#fff}@media(max-width:680px){.module-header{align-items:stretch;flex-direction:column}.user-ad-item{grid-template-columns:42px minmax(0,1fr)}.ad-bank-icon{width:42px;height:42px}.ad-actions{grid-column:1/-1;justify-content:flex-start}.ad-item-facts{gap:10px;flex-wrap:wrap}}
.module-view{max-width:980px;margin:0 auto;padding-bottom:32px}.module-header{align-items:center;padding:22px 24px;margin-bottom:16px;border:1px solid #edf0f2;border-radius:14px;background:linear-gradient(110deg,#fff 0%,#fff 70%,#fff8f4 100%);box-shadow:0 8px 24px rgba(32,42,53,.05)}.module-header>div{min-width:0}.module-kicker{display:inline-flex;align-items:center;gap:7px}.module-kicker::before{width:7px;height:7px;border-radius:50%;content:'';background:#ef8354}.module-header h1{font-size:25px;line-height:1.45}.module-header p{line-height:1.8}.status-tabs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;padding:6px;margin-bottom:16px;border:1px solid #edf0f2;border-radius:12px;background:#fff}.status-tabs button{justify-content:center;padding:10px 8px;border:0;border-radius:8px}.status-tabs button.active{border:0;background:#fff4f1;color:#a62626}.status-tabs span{min-width:22px;text-align:center}.module-empty{display:flex;align-items:center;justify-content:center;min-height:240px;padding:32px 20px;border:1px dashed #dfe5e8;border-radius:14px;background:#fff;text-align:center;flex-direction:column}.module-empty>i{display:grid;place-items:center;width:52px;height:52px;margin-bottom:12px;border-radius:16px;background:#fff4f1;color:#a62626;font-size:22px}.module-empty h2{margin:0 0 16px;color:#35434b;font-size:16px}.user-ads-list{gap:14px}.user-ad-item{padding:19px;border-radius:12px;box-shadow:0 5px 16px rgba(32,42,53,.035)}@media(max-width:680px){.module-view{padding-bottom:20px}.module-header{align-items:stretch;padding:18px;gap:16px}.module-header h1{font-size:21px}.primary-action{width:100%}.status-tabs{grid-template-columns:repeat(2,minmax(0,1fr));gap:5px}.status-tabs button{font-size:11px}.module-empty{min-height:210px;padding:26px 16px}}
</style>
